export type Lang = "en" | "hi" | "ta" | "te" | "bn" | "mr" | "gu" | "kn";

export const LANGUAGES: Lang[] = ["en", "hi", "ta", "te", "bn", "mr", "gu", "kn"];

// Displayed in the dropdown using each language's own script (autonym),
// not translated names, since that's what a native reader recognizes fastest.
export const LANGUAGE_LABELS: Record<Lang, string> = {
  en: "English",
  hi: "हिंदी",
  ta: "தமிழ்",
  te: "తెలుగు",
  bn: "বাংলা",
  mr: "मराठी",
  gu: "ગુજરાતી",
  kn: "ಕನ್ನಡ",
};

export function parseLang(value: string | undefined | null): Lang {
  return value && (LANGUAGES as string[]).includes(value) ? (value as Lang) : "en";
}

